def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    if start == goal:
        r, c = start
        if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
            return [start]
        else:
            return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(*start) or not is_valid(*goal):
        return []

    import heapq
    heap = []
    heapq.heappush(heap, (0, start[0], start[1]))
    prev = {}
    visited = set()
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    found = False

    while heap:
        dist, r, c = heapq.heappop(heap)
        if (r, c) in visited:
            continue
        visited.add((r, c))
        if (r, c) == goal:
            found = True
            break
        for dr, dc in directions:
            new_r, new_c = r + dr, c + dc
            if is_valid(new_r, new_c):
                if (new_r, new_c) not in prev:
                    heapq.heappush(heap, (dist + 1, new_r, new_c))
                    prev[(new_r, new_c)] = (r, c)

    if not found:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = prev.get(current)
        if current is None:
            return []
    path.append(start)
    path.reverse()
    return path

