def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    INF = float('inf')
    distance = [[INF] * cols for _ in range(rows)]
    predecessor = [[None] * cols for _ in range(rows)]
    distance[start[0]][start[1]] = 0
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    for _ in range(rows * cols):
        updated = False
        for row in range(rows):
            for col in range(cols):
                if distance[row][col] == INF:
                    continue
                for dr, dc in directions:
                    new_row, new_col = row + dr, col + dc
                    if 0 <= new_row < rows and 0 <= new_col < cols:
                        if grid[new_row][new_col] == '.':
                            if distance[new_row][new_col] > distance[row][col] + 1:
                                distance[new_row][new_col] = distance[row][col] + 1
                                predecessor[new_row][new_col] = (row, col)
                                updated = True
        if not updated:
            break
        if distance[goal[0]][goal[1]] != INF:
            break
    if distance[goal[0]][goal[1]] == INF:
        return []
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = predecessor[current[0]][current[1]]
    path.reverse()
    return path

